CREATE TABLE shipments (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, booking_no VARCHAR2(50) UNIQUE NOT NULL, vessel_name VARCHAR2(100), origin_port VARCHAR2(10), destination_port VARCHAR2(10), container_type VARCHAR2(20), cargo_weight_tons NUMBER(12,3), status VARCHAR2(20), created_at TIMESTAMP);
CREATE TABLE route_master (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, origin_port VARCHAR2(10), destination_port VARCHAR2(10), distance_km NUMBER(12,2), origin_country VARCHAR2(100), destination_country VARCHAR2(100), CONSTRAINT uk_route UNIQUE(origin_port,destination_port));
CREATE TABLE emission_calculation (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, shipment_id NUMBER, route_id NUMBER, distance_km NUMBER(12,2), weight_tons NUMBER(12,3), emission_factor NUMBER(12,6), total_co2_kg NUMBER(15,3), calculated_at TIMESTAMP);
CREATE TABLE report_audit (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, report_type VARCHAR2(30), generated_at TIMESTAMP);
